  const totalUsd = cashUsd + invested;
  const targetSum = symbols.reduce((s, k) => s + cfg.targets[k], 0);
  const cashTargetPct = 100 - targetSum;
  const pct = (v) => totalUsd > 0 ? v / totalUsd * 100 : 0;
