    const amountUsd = cents(Math.abs(diffUsd));
    if (amountUsd < cfg.minTradeUsd) continue;
    if (diffUsd < 0) sells.push({ side: "sell", symbol: r.symbol, amountUsd });
    else buys.push({ side: "buy", symbol: r.symbol, amountUsd });
